// Build a minimal valid PDF from scratch using raw PDF spec
const item = $input.first().json;

const orderId = item.order_id || 'N/A';
const customerName = item.customer_name || 'N/A';
const customerAddress = item.customer_address || 'N/A';
const customerEmail = item.customer_email || 'N/A';
const confirmedBy = item.confirmed_by || 'N/A';
const confirmedAt = item.confirmed_at || 'N/A';
const items = Array.isArray(item.items) ? item.items : [];

// Build item lines text
const itemLines = items.map((it, i) => {
  const sku = it.sku || '';
  const name = (it.name || '').replace(/[()\\]/g, ' ');
  const qty = it.qty || 0;
  const unit = it.unit || '';
  return `SKU: ${sku}  |  ${name}  |  Qty: ${qty} ${unit}`;
});

// We'll build a simple PDF with text streams
// Each content line needs to be a PDF text operation
const toSafePDF = (s) => String(s).replace(/[\\()]/g, '\\$&').replace(/\n/g, ' ');

const lines = [
  '=== GOLDEN HARVEST S.A. ===',
  'SHIPPING SLIP / REMITO',
  '',
  `Order ID:      ${orderId}`,
  `Customer:      ${customerName}`,
  `Address:       ${customerAddress}`,
  `Email:         ${customerEmail}`,
  `Confirmed by:  ${confirmedBy}`,
  `Confirmed at:  ${confirmedAt}`,
  '',
  '--- ITEMS ---',
  ...itemLines,
  '',
  '--- END OF DOCUMENT ---',
];

// Build PDF content stream
let textOps = '';
let y = 750;
for (const line of lines) {
  textOps += `BT /F1 11 Tf 40 ${y} Td (${toSafePDF(line)}) Tj ET\n`;
  y -= 18;
  if (y < 50) break; // page overflow guard
}

const streamContent = textOps;
const streamLength = Buffer.byteLength(streamContent, 'utf8');

const pdfContent = [
  '%PDF-1.4',
  '1 0 obj<</Type /Catalog /Pages 2 0 R>>endobj',
  '2 0 obj<</Type /Pages /Kids[3 0 R] /Count 1>>endobj',
  '3 0 obj<</Type /Page /Parent 2 0 R /MediaBox[0 0 612 792] /Contents 4 0 R /Resources<</Font<</F1 5 0 R>>>>>>endobj',
  `4 0 obj<</Length ${streamLength}>>`,
  'stream',
  streamContent,
  'endstream',
  'endobj',
  '5 0 obj<</Type /Font /Subtype /Type1 /BaseFont /Courier>>endobj',
  'xref',
  '0 6',
  '0000000000 65535 f ',
].join('\n');

// Compute xref offsets properly by rebuilding
const objects = [
  '%PDF-1.4\n',
  '1 0 obj<</Type /Catalog /Pages 2 0 R>>endobj\n',
  '2 0 obj<</Type /Pages /Kids[3 0 R] /Count 1>>endobj\n',
  `3 0 obj<</Type /Page /Parent 2 0 R /MediaBox[0 0 612 792] /Contents 4 0 R /Resources<</Font<</F1 5 0 R>>>>>>endobj\n`,
  `4 0 obj<</Length ${streamLength}>>\nstream\n${streamContent}\nendstream\nendobj\n`,
  '5 0 obj<</Type /Font /Subtype /Type1 /BaseFont /Courier>>endobj\n',
];

let offsets = [];
let offset = 0;
offsets.push(0); // object 0 (free)
for (let i = 0; i < objects.length; i++) {
  if (i === 0) { offset += Buffer.byteLength(objects[0], 'latin1'); continue; }
  offsets.push(offset);
  offset += Buffer.byteLength(objects[i], 'latin1');
}

const xrefOffset = offset;
const xrefTable = [
  'xref',
  `0 ${objects.length}`,
  '0000000000 65535 f ',
  ...offsets.slice(1).map(o => String(o).padStart(10, '0') + ' 00000 n '),
].join('\n');

const trailer = `\ntrailer<</Size ${objects.length} /Root 1 0 R>>\nstartxref\n${xrefOffset}\n%%EOF`;

const fullPdf = objects.join('') + xrefTable + trailer;
const pdfBuffer = Buffer.from(fullPdf, 'latin1');
const base64Pdf = pdfBuffer.toString('base64');

return [{
  json: { ...item, pdf_generated: true },
  binary: {
    data: {
      data: base64Pdf,
      mimeType: 'application/pdf',
      fileName: `shipping_${orderId}.pdf`,
      fileExtension: 'pdf',
    }
  }
}];
